pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Only test when the caller is the authorized address
        vm.assume(msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Ensure arrays have same length
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        // Bound v[i] to avoid overflow in the multiplication check
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }

        // Call the function and capture the return value
        bool result = c.transfer(_tos, v);

        // The buggy version always returns false, so the rule is that transfer returns true
        assertTrue(result, "transfer should return true when requirements are met");
    }
}

